"""Minimal JSON-Schema style validator with a self-contained document parser."""
import re

_NUMBER_RE = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?")


class ValidationError(ValueError):
    """Raised when a schema document or an instance fails validation."""


class _JsonParser:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def _error(self, msg):
        raise ValidationError("schema parse error at offset {}: {}".format(self.pos, msg))

    def parse(self):
        self._ws()
        value = self._value()
        self._ws()
        if self.pos != len(self.text):
            self._error("unexpected trailing data")
        return value

    def _ws(self):
        while self.pos < len(self.text) and self.text[self.pos] in " \t\r\n":
            self.pos += 1

    def _peek(self):
        if self.pos >= len(self.text):
            self._error("unexpected end of input")
        return self.text[self.pos]

    def _value(self):
        c = self._peek()
        if c == "{":
            return self._object()
        if c == "[":
            return self._array()
        if c == '"':
            return self._string()
        for lit, val in (("true", True), ("false", False), ("null", None)):
            if self.text.startswith(lit, self.pos):
                self.pos += len(lit)
                return val
        return self._number()

    def _number(self):
        m = _NUMBER_RE.match(self.text, self.pos)
        if m is None:
            self._error("invalid number")
        raw = m.group(0)
        self.pos = m.end()
        try:
            return int(raw)
        except ValueError:
            return float(raw)

    def _string(self):
        self.pos += 1  # opening quote
        out = []
        while True:
            if self.pos >= len(self.text):
                self._error("unterminated string")
            c = self.text[self.pos]
            if c == '"':
                self.pos += 1
                return "".join(out)
            if c == "\\":
                out.append(self._escape())
            else:
                out.append(c)
                self.pos += 1

    def _escape(self):
        # invariant: self.text[self.pos] == "\\"
        if self.pos + 1 >= len(self.text):
            self._error("bad escape at end of input")
        nxt = self.text[self.pos + 1]
        simple = {'"': '"', "\\": "\\", "/": "/",
                  "b": "\b", "f": "\f", "n": "\n", "r": "\r", "t": "\t"}
        if nxt == "u":
            # BENCHMARK BUG: \uXXXX escapes are not decoded; the literal
            # letter 'u' is emitted and the hex digits leak through as text.
            self.pos += 2
            return "u"
        if nxt in simple:
            self.pos += 2
            return simple[nxt]
        self._error("invalid escape \\{}".format(nxt))

    def _object(self):
        self.pos += 1  # {
        obj = {}
        self._ws()
        if self._peek() == "}":
            self.pos += 1
            return obj
        while True:
            self._ws()
            if self._peek() != '"':
                self._error("expected object key")
            key = self._string()
            self._ws()
            if self._peek() != ":":
                self._error("expected ':' after object key")
            self.pos += 1
            obj[key] = self._value()
            self._ws()
            c = self._peek()
            if c == ",":
                self.pos += 1
                continue
            if c == "}":
                self.pos += 1
                return obj
            self._error("expected ',' or '}' in object")

    def _array(self):
        self.pos += 1  # [
        arr = []
        self._ws()
        if self._peek() == "]":
            self.pos += 1
            return arr
        while True:
            arr.append(self._value())
            self._ws()
            c = self._peek()
            if c == ",":
                self.pos += 1
                continue
            if c == "]":
                self.pos += 1
                return arr
            self._error("expected ',' or ']' in array")


def load_schema(text):
    """Parse a JSON schema document into a Python structure."""
    return _JsonParser(text).parse()


def validate(instance, schema):
    """Validate ``instance`` against ``schema``; returns True or raises."""
    expected = schema.get("type")
    if expected == "object":
        _check_object(instance, schema)
    elif expected == "array":
        _check_array(instance, schema)
    elif expected == "string":
        _check_string(instance)
    elif expected == "integer":
        _check_integer(instance)
    elif expected == "number":
        _check_number(instance)
    elif expected == "boolean":
        _check_boolean(instance)
    elif expected == "null":
        _check_null(instance)
    elif expected is None:
        if isinstance(instance, dict):
            _check_object(instance, schema)
        elif isinstance(instance, list):
            _check_array(instance, schema)
    else:
        raise ValidationError("unknown schema type: {!r}".format(expected))
    return True


def _check_object(instance, schema):
    if not isinstance(instance, dict):
        raise ValidationError("expected object, got {}".format(type(instance).__name__))
    for required in schema.get("required", []):
        if required not in instance:
            raise ValidationError("missing required property: {!r}".format(required))
    properties = schema.get("properties", {})
    for name, subschema in properties.items():
        if name in instance:
            validate(instance[name], subschema)


def _check_array(instance, schema):
    if not isinstance(instance, list):
        raise ValidationError("expected array, got {}".format(type(instance).__name__))
    items = schema.get("items")
    if items is not None:
        for element in instance:
            validate(element, items)


def _check_string(instance):
    if not isinstance(instance, str):
        raise ValidationError("expected string, got {}".format(type(instance).__name__))
    # BENCHMARK BUG: control characters (NUL, newline, ...) are accepted here.


def _check_integer(instance):
    if isinstance(instance, bool) or not isinstance(instance, int):
        raise ValidationError("expected integer")


def _check_number(instance):
    if isinstance(instance, bool) or not isinstance(instance, (int, float)):
        raise ValidationError("expected number")


def _check_boolean(instance):
    if not isinstance(instance, bool):
        raise ValidationError("expected boolean")


def _check_null(instance):
    if instance is not None:
        raise ValidationError("expected null")

